            // Runtime compatibility layer: keep the UI localized without masking fresh analysis.
// Incoming localized text wins; the static Chinese benchmark is fallback only
// when a proxy field is missing or still English.
(() => {
  const fallbackContract = window.PROTOTYPE_DATA_CONTRACT || {};
  const fallbackDatasets = fallbackContract.datasets?.benchmark || window.BENCHMARK_DATA || {};
  const hasCjk = (value) => typeof value === 'string' && /[\u3400-\u9fff]/.test(value);
  const chooseText = (remoteValue, fallbackValue) => {
    if (remoteValue == null || remoteValue === '') return fallbackValue ?? remoteValue;
    if (typeof remoteValue !== 'string') return remoteValue;
    if (hasCjk(remoteValue) || !hasCjk(fallbackValue)) return remoteValue;
    return fallbackValue;
  };
  const chooseObject = (remoteValue, fallbackValue) => {
    if (!remoteValue) return fallbackValue;
    return hasCjk(JSON.stringify(remoteValue)) || !fallbackValue ? remoteValue : fallbackValue;
  };
  const mergeCandidate = (remoteCandidate, fallbackCandidate) => {
    const merged = { ...(fallbackCandidate || {}), ...(remoteCandidate || {}) };
    ['text', 'status', 'confirmation', 'invalidation', 'callout'].forEach((key) => {
      merged[key] = chooseText(remoteCandidate?.[key], fallbackCandidate?.[key]);
    });
    merged.confidence = remoteCandidate?.confidence ?? fallbackCandidate?.confidence;
    merged.geometry = remoteCandidate?.geometry || fallbackCandidate?.geometry;
    return merged;
  };
  const mergeDataset = (remote, fallback) => {
    if (!fallback) return remote || {};
    const merged = { ...fallback, ...(remote || {}) };
    ['pattern', 'patternStatus', 'thesis', 'wyckoff', 'weeklyWyckoff', 'options', 'business'].forEach((key) => {
      merged[key] = chooseText(remote?.[key], fallback[key]);
    });
    merged.bars = Array.isArray(remote?.bars) && remote.bars.length >= 20 ? remote.bars : (fallback.bars || []);
    merged.patternCandidates = {
      ...(fallback.patternCandidates || {}),
      ...(remote?.patternCandidates || {}),
      primary: mergeCandidate(remote?.patternCandidates?.primary, fallback.patternCandidates?.primary),
      secondary: mergeCandidate(remote?.patternCandidates?.secondary, fallback.patternCandidates?.secondary)
    };
    merged.gexViews = remote?.gexViews || fallback.gexViews;
    return merged;
  };
  const applyLocalizedContract = () => {
    const remote = window.PROTOTYPE_DATA_CONTRACT || {};
    if (remote === fallbackContract) return;
    const remoteDatasets = remote.datasets?.benchmark || {};
    const tickers = new Set([...Object.keys(fallbackDatasets), ...Object.keys(remoteDatasets)]);
    const benchmark = Object.fromEntries([...tickers].map((ticker) => [ticker, mergeDataset(remoteDatasets[ticker], fallbackDatasets[ticker])]));
    const fallbackRuns = fallbackContract.analysisRuns || [];
    const runs = (remote.analysisRuns?.length ? remote.analysisRuns : fallbackRuns).map((run) => {
      const fallback = fallbackRuns.find((item) => item.runId === run.runId) || fallbackRuns.find((item) => item.ticker === run.ticker && item.runType === run.runType);
      if (!fallback) return run;
      const merged = { ...fallback, ...run };
      ['thesis', 'pattern', 'confirmation', 'invalidation', 'wyckoff', 'weeklyWyckoff', 'options', 'business'].forEach((key) => {
        merged[key] = chooseText(run[key], fallback[key]);
      });
      return merged;
    });
    window.PROTOTYPE_DATA_CONTRACT = {
      ...remote,
      coverage: remote.coverage?.length ? remote.coverage : fallbackContract.coverage,
      analysisRuns: runs,
      datasets: {
        ...(remote.datasets || {}),
        benchmark,
        analysisDetails: chooseObject(remote.datasets?.analysisDetails, fallbackContract.datasets?.analysisDetails),
        weeklyHistory: remote.datasets?.weeklyHistory || fallbackContract.datasets?.weeklyHistory
      }
    };
  };
  if (window.__PROTOTYPE_DATA_PROXY_DONE) applyLocalizedContract();
  else window.addEventListener('prototype-data-ready', applyLocalizedContract, { once: true });
})();
